import { createChart } from '../../core/utHelper';
import { EChartsType } from '../../../../src/echarts';

describe('aria', function () {
    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        chart.dispose();
    });

    it('should set role="img" on the chart container', function () {
        chart.setOption({
            aria: { enabled: true },
            series: [{ type: 'pie', data: [{ name: 'A', value: 1 }] }]
        });
        expect(chart.getDom().getAttribute('role')).toEqual('img');
    });

    it('should exclude dimensions listed in aria.label.data.excludeDimensionId', function () {
        const source = [
            ['product', 'hidden', 'amount'],
            ['Matcha', 111, 43.3],
            ['Milk', 222, 83.1]
        ];
        chart.setOption({
            aria: {
                enabled: true,
                label: {
                    data: {
                        excludeDimensionId: [1]
                    }
                }
            },
            dataset: { source },
            xAxis: { type: 'category' },
            yAxis: {},
            series: [{ type: 'bar' }]
        });

        const ariaLabel = chart.getDom().getAttribute('aria-label');
        expect(ariaLabel).not.toContain('111');
        expect(ariaLabel).not.toContain('222');
        expect(ariaLabel).toContain('43.3');
        expect(ariaLabel).toContain('83.1');

        // The aria generation must not mutate the user data.
        expect(source[1]).toEqual(['Matcha', 111, 43.3]);
        expect(source[2]).toEqual(['Milk', 222, 83.1]);
    });
});

