import { createChart, getECModel } from '../../core/utHelper';
import { EChartsType } from '../../../../src/echarts';
import CartesianAxisModel from '../../../../src/coord/cartesian/AxisModel';

describe('axis_customValues', function () {
    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        chart.dispose();
    });

    function getYAxis() {
        return (getECModel(chart).getComponent('yAxis', 0) as CartesianAxisModel).axis;
    }

    it('axisLabel.customValues places labels at the given values', function () {
        chart.setOption({
            xAxis: { type: 'category', data: ['a', 'b', 'c'] },
            yAxis: {
                type: 'value',
                min: 0,
                max: 100,
                axisLabel: { customValues: [10, 55, 90, 1000] }
            },
            series: [{ type: 'bar', data: [1, 2, 3] }]
        });

        const labels = getYAxis().getViewLabels();
        expect(labels.map(item => item.tickValue)).toEqual([10, 55, 90]);
    });

    it('axisTick.customValues places ticks at the given values', function () {
        chart.setOption({
            xAxis: { type: 'category', data: ['a', 'b', 'c'] },
            yAxis: {
                type: 'value',
                min: 0,
                max: 100,
                axisTick: { show: true, customValues: [20, 60] }
            },
            series: [{ type: 'bar', data: [1, 2, 3] }]
        });

        const axis = getYAxis();
        const ticks = axis.getTicksCoords({
            tickModel: (axis.model as CartesianAxisModel).getModel('axisTick') as any
        });
        expect(ticks.map(item => item.tickValue)).toEqual([20, 60]);
    });

    it('customValues works on time axis with date strings', function () {
        chart.setOption({
            xAxis: {
                type: 'time',
                min: '2024-01-01',
                max: '2024-01-10',
                axisLabel: { customValues: ['2024-01-03', '2024-01-07'] }
            },
            yAxis: {},
            series: [{ type: 'line', data: [['2024-01-02', 1], ['2024-01-09', 2]] }]
        });

        const axis = (getECModel(chart).getComponent('xAxis', 0) as CartesianAxisModel).axis;
        const labels = axis.getViewLabels();
        expect(labels.length).toEqual(2);
        expect(labels[0].tickValue).toEqual(+new Date('2024-01-03'));
        expect(labels[1].tickValue).toEqual(+new Date('2024-01-07'));
    });
});

