new_method = """    /**
     * Large data down sampling that preserves the local extrema of each frame.
     * Both the minimum and the maximum of a frame are kept, and they are emitted
     * in their original data order so the shape of the line is not distorted.
     */
    minmaxDownSample(
        valueDimension: DimensionIndex,
        rate: number
    ): DataStore {
        const target = this.clone([valueDimension], true);
        const targetStorage = target._chunks;
        const dimStore = targetStorage[valueDimension];
        const len = this.count();
        const frameSize = Math.max(Math.floor(1 / rate), 1);

        // At most one NaN, one min and one max are kept per frame, which never
        // exceeds the frame size, so `len` slots are always enough.
        const newIndices = new (getIndicesCtor(this._rawCount))(len);

        let offset = 0;
        for (let i = 0; i < len; i += frameSize) {
            const thisFrameSize = Math.min(frameSize, len - i);

            let minIndex = -1;
            let maxIndex = -1;
            let firstNaNIndex = -1;
            let minValue = Infinity;
            let maxValue = -Infinity;

            for (let k = 0; k < thisFrameSize; k++) {
                const value = dimStore[this.getRawIndex(i + k)] as number;
                if (isNaN(value)) {
                    if (firstNaNIndex < 0) {
                        firstNaNIndex = i + k;
                    }
                    continue;
                }
                if (value < minValue) {
                    minValue = value;
                    minIndex = i + k;
                }
                if (value > maxValue) {
                    maxValue = value;
                    maxIndex = i + k;
                }
            }

            // Keep the original order of the picked points, otherwise the line
            // would zigzag backwards.
            let lastIndex = -1;
            for (let k = 0; k < thisFrameSize; k++) {
                const idx = i + k;
                if (idx !== firstNaNIndex && idx !== minIndex && idx !== maxIndex) {
                    continue;
                }
                if (idx === lastIndex) {
                    continue;
                }
                lastIndex = idx;
                newIndices[offset++] = this.getRawIndex(idx);
            }
        }

        target._count = offset;
        target._indices = newIndices;
        target._updateGetRawIdx();

        return target;
    }

