import SeriesData from '../../../../src/data/SeriesData';
import Model from '../../../../src/model/Model';

describe('minmaxDownSample', function () {

    function createData(values: number[]) {
        const data = new SeriesData(['x', 'y'], new Model());
        data.initData(values.map((v, i) => [i, v]));
        return data;
    }

    it('keeps both the trough and the peak of every frame', function () {
        // frame size 4: [5, 1, 4, 2] -> min 1 (idx 1), max 5 (idx 0)
        //               [3, 9, 6, 7] -> min 3 (idx 4), max 9 (idx 5)
        const data = createData([5, 1, 4, 2, 3, 9, 6, 7]);
        const sampled = data.minmaxDownSample('y', 1 / 4);

        const values: number[] = [];
        sampled.each('y', (v: number) => values.push(v));
        expect(values).toEqual([5, 1, 3, 9]);
    });

    it('does not lose troughs of data with a non-zero baseline', function () {
        // With the old abs-based sampler every frame would report only the
        // largest absolute value (i.e. the peaks), hiding all troughs.
        const data = createData([50, 49, 51, 50, 50, 52, 48, 50]);
        const sampled = data.minmaxDownSample('y', 1 / 4);

        const values: number[] = [];
        sampled.each('y', (v: number) => values.push(v));
        expect(values).toContain(49);
        expect(values).toContain(51);
        expect(values).toContain(52);
        expect(values).toContain(48);
    });

    it('keeps the original point order inside a frame', function () {
        const data = createData([1, 9, 2, 8]);
        const sampled = data.minmaxDownSample('y', 1 / 4);

        const xs: number[] = [];
        sampled.each('x', (v: number) => xs.push(v));
        // Ascending, never going backwards.
        for (let i = 1; i < xs.length; i++) {
            expect(xs[i]).toBeGreaterThan(xs[i - 1]);
        }
    });
});

