import { createHashMap } from 'zrender/src/core/util';
import { inheritDefaultOption } from '../../util/component';
import ChartView from '../../view/Chart';
import SeriesModel from '../../model/Series';
import CustomSeriesModel, { CustomSeriesOption, CustomSeriesRenderItem } from './CustomSeries';
import CustomChartView from './CustomView';

const registeredCustomSeries = createHashMap<CustomSeriesRenderItem>();

/**
 * Register a reusable custom series, so that it can be used like any other
 * series type:
 *
 * ```js
 * echarts.use(function (registers) {
 *     registers.registerCustomSeries('myShape', renderItem);
 * });
 * // ...
 * option = { series: [{ type: 'myShape', data: [...] }] };
 * ```
 *
 * The `renderItem` of the registered series can still be overridden by the
 * `renderItem` given in the series option.
 */
export function registerCustomSeries(seriesType: string, renderItem: CustomSeriesRenderItem): void {
    if (registeredCustomSeries.get(seriesType)) {
        // Already registered, only refresh the `renderItem`.
        registeredCustomSeries.set(seriesType, renderItem);
        return;
    }
    registeredCustomSeries.set(seriesType, renderItem);

    class ReusableCustomSeriesModel extends CustomSeriesModel {
        static type = 'series.' + seriesType;
        readonly type = ReusableCustomSeriesModel.type;

        static dependencies = CustomSeriesModel.dependencies;

        static defaultOption: CustomSeriesOption = inheritDefaultOption(
            CustomSeriesModel.defaultOption,
            { renderItem: renderItem }
        );
    }

    class ReusableCustomChartView extends CustomChartView {
        static type = 'series.' + seriesType;
        readonly type = ReusableCustomChartView.type;
    }

    SeriesModel.registerClass(ReusableCustomSeriesModel);
    ChartView.registerClass(ReusableCustomChartView);
}

export function getRegisteredCustomSeries(seriesType: string): CustomSeriesRenderItem {
    return registeredCustomSeries.get(seriesType);
}

