import { createChart } from '../../core/utHelper';
import { EChartsType } from '../../../../src/echarts';
import { use } from '../../../../src/extension';
import type { EChartsExtensionInstallRegisters } from '../../../../src/extension';

describe('custom_reusableSeries', function () {
    let chart: EChartsType;
    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        chart.dispose();
    });

    it('passes series.itemPayload to renderItem params', function () {
        const payload = { color: 'red', tag: 'shared' };
        const seenPayloads: unknown[] = [];

        chart.setOption({
            xAxis: {},
            yAxis: {},
            series: [{
                type: 'custom',
                itemPayload: payload,
                renderItem(params: any, api: any) {
                    seenPayloads.push(params.itemPayload);
                    return {
                        type: 'circle',
                        shape: { cx: api.value(0), cy: api.value(1), r: 3 }
                    };
                },
                data: [[1, 2], [3, 4]]
            }]
        });

        expect(seenPayloads.length).toBeGreaterThan(0);
        seenPayloads.forEach(p => expect(p).toBe(payload));
    });

    it('renderItem params.itemPayload defaults to an empty object', function () {
        let seen: any;
        chart.setOption({
            xAxis: {},
            yAxis: {},
            series: [{
                type: 'custom',
                renderItem(params: any, api: any) {
                    seen = params.itemPayload;
                    return {
                        type: 'circle',
                        shape: { cx: api.value(0), cy: api.value(1), r: 3 }
                    };
                },
                data: [[1, 2]]
            }]
        });
        expect(seen).toEqual({});
    });

    it('registers a reusable custom series through the installer flow', function () {
        let called = 0;
        use(function (registers: EChartsExtensionInstallRegisters) {
            registers.registerCustomSeries('utTriangle', function (params: any, api: any) {
                called++;
                return {
                    type: 'circle',
                    shape: { cx: api.value(0), cy: api.value(1), r: 3 }
                };
            });
        });

        chart.setOption({
            xAxis: {},
            yAxis: {},
            series: [{
                type: 'utTriangle',
                data: [[1, 2], [3, 4]]
            }]
        } as any);

        expect(called).toBeGreaterThan(0);
        expect(chart.getModel().getSeriesByIndex(0).subType).toEqual('utTriangle');
    });
});

